const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || args.instruction || '').trim();
const startAt = String(source.startAt || source.start || args.startAt || args.start || payload.startAt || payload.start || new Date().toISOString()).trim();
const endAt = String(source.endAt || source.end || args.endAt || args.end || payload.endAt || payload.end || new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()).trim();
const durationMinutes = Math.max(15, Math.min(Number(source.durationMinutes || args.durationMinutes || payload.durationMinutes || 60) || 60, 1440));
const calendarId = String(source.calendarId || args.calendarId || payload.calendarId || 'primary').trim();
return [{ json: { ...source, payload, message, chatId, rawText, startAt, endAt, durationMinutes, calendarId, hasTarget: true } }];

const source = $('Prepare Action').item.json || {};
const events = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.start || item.end);
const windowStart = new Date(source.startAt || Date.now());
const windowEnd = new Date(source.endAt || Date.now() + 24 * 60 * 60 * 1000);
const durationMinutes = Math.max(15, Math.min(Number(source.durationMinutes || 60) || 60, 1440));
const durationMs = durationMinutes * 60 * 1000;
const stepMs = 15 * 60 * 1000;

const busy = events
  .map((ev) => {
    const startRaw = ev.start?.dateTime || ev.start?.date || ev.start || ev.startAt || '';
    const endRaw = ev.end?.dateTime || ev.end?.date || ev.end || ev.endAt || '';
    return { start: new Date(startRaw), end: new Date(endRaw) };
  })
  .filter((ev) => Number.isFinite(ev.start.getTime()) && Number.isFinite(ev.end.getTime()))
  .sort((a, b) => a.start - b.start);

function overlaps(candidateStart, candidateEnd, interval) {
  return candidateStart < interval.end && candidateEnd > interval.start;
}

const slots = [];
for (let cursor = new Date(windowStart); cursor.getTime() + durationMs <= windowEnd.getTime(); cursor = new Date(cursor.getTime() + stepMs)) {
  const candidateEnd = new Date(cursor.getTime() + durationMs);
  const conflict = busy.some((interval) => overlaps(cursor, candidateEnd, interval));
  if (!conflict) {
    slots.push({ start: cursor.toISOString(), end: candidateEnd.toISOString() });
  }
  if (slots.length >= 8) break;
}

return [{ json: { ...source, ok: true, slots } }];

const source = $('Prepare Action').item.json || {};
const slots = ($json.slots || []).slice(0, 3);
const tz = 'Asia/Ho_Chi_Minh';
const formatter = new Intl.DateTimeFormat('vi-VN', {
  timeZone: tz,
  hour: '2-digit',
  minute: '2-digit',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
});

const lines = [];
if (!slots.length) {
  lines.push('Mia chưa tìm thấy khung giờ rảnh phù hợp trong khoảng bạn yêu cầu.');
} else {
  lines.push('Các khung giờ rảnh gợi ý:');
  slots.forEach((slot, index) => {
    lines.push(`${index + 1}. ${formatter.format(new Date(slot.start))} → ${formatter.format(new Date(slot.end))}`);
  });
}
if (source.calendarId) lines.push(`Calendar: ${source.calendarId}`);
if (source.startAt && source.endAt) lines.push(`Khoảng kiểm tra: ${source.startAt} - ${source.endAt}`);
return [{ json: { chatId: source.chatId || '', text: lines.join('\n').trim(), slots } }];
